import random
import string

# Generate valid hex-encoded strings suitable for r_search_keyword_new_hex and
# r_search_keyword_new_hexmask fuzzers.
# We return two NUL-terminated strings: pattern\0mask_or_hexmask\0

HEX_DIGITS = "0123456789abcdef"

def _hex_byte(val: int) -> str:
    return f"{val & 0xFF:02x}"

def _mk_sequence_bytes(seq):
    return ''.join(_hex_byte(b) for b in seq)

def _mk_spaced(hexstr: str, sep: str) -> str:
    return sep.join(hexstr[i:i+2] for i in range(0, len(hexstr), 2))

def _safe_randint(rng: random.Random, a: int, b: int) -> int:
    if a > b:
        return a
    return rng.randint(a, b)

def _pattern_templates(rng: random.Random) -> str:
    choice = rng.randrange(7)
    # Ensure sensible bounds
    max_bytes = _safe_randint(rng, 8, 40)
    if choice == 0:
        # NOP sled-like (x86 0x90)
        n = _safe_randint(rng, 8, max_bytes)
        return _mk_sequence_bytes([0x90] * n)
    elif choice == 1:
        # Alternating 00/FF
        n = _safe_randint(rng, 8, max_bytes)
        return _mk_sequence_bytes([0x00 if i % 2 == 0 else 0xFF for i in range(n)])
    elif choice == 2:
        # Incremental bytes
        start = _safe_randint(rng, 0, 200)
        n = _safe_randint(rng, 8, max_bytes)
        return _mk_sequence_bytes([(start + i) % 256 for i in range(n)])
    elif choice == 3:
        # Common prologue + random tail
        base = [0x55, 0x48, 0x89, 0xE5]
        rem = max(0, max_bytes - len(base))
        tail_n = _safe_randint(rng, 0, rem)
        tail = [rng.randrange(256) for _ in range(tail_n)]
        return _mk_sequence_bytes(base + tail)
    elif choice == 4:
        # Repeating short pattern
        unit_len = _safe_randint(rng, 2, 6)
        unit = [rng.randrange(256) for _ in range(unit_len)]
        reps = max(1, max_bytes // max(1, unit_len))
        reps = _safe_randint(rng, 4, max(4, reps))
        seq = (unit * reps)[:max_bytes]
        return _mk_sequence_bytes(seq)
    elif choice == 5:
        # Random bytes
        n = _safe_randint(rng, 8, max_bytes)
        return _mk_sequence_bytes([rng.randrange(256) for _ in range(n)])
    else:
        # ASCII string in hex
        ascii_pool = "MZELFPE\x00\x00\x01\x02\x03" + ''.join(chr(0x20 + (rng.randrange(95))) for _ in range(20))
        strlen = _safe_randint(rng, 6, 24)
        s = ''.join(rng.choice(ascii_pool) for _ in range(strlen))
        return ''.join(f"{ord(c):02x}" for c in s)

def _maybe_separate(hexstr: str, rng: random.Random) -> str:
    style = rng.randrange(4)
    if style == 0:
        return hexstr
    elif style == 1:
        return _mk_spaced(hexstr, ' ')
    elif style == 2:
        return _mk_spaced(hexstr, ':')
    else:
        return _mk_spaced(hexstr, ' ' if rng.random() < 0.5 else '-')

def _truncate_to_128(hexlike: str) -> str:
    # Try to keep even number of hex digits and not split separators poorly
    if len(hexlike) <= 128:
        return hexlike
    # Remove separators, trim, then reinsert spaces
    hex_only = ''.join(ch for ch in hexlike if ch in string.hexdigits)
    hex_only = hex_only[:128 - (128 % 2)]
    spaced = _mk_spaced(hex_only, ' ')
    return spaced if len(spaced) <= 128 else spaced[:128]

def _make_hex_and_mask(rng: random.Random):
    hk_raw = _pattern_templates(rng)
    hk = _maybe_separate(hk_raw, rng)
    hk = _truncate_to_128(hk)
    # Compute number of bytes (from hex digits only)
    nibs = [c for c in hk if c in string.hexdigits]
    nbytes = max(1, len(nibs) // 2)
    mask_bytes = []
    for _ in range(nbytes):
        mb_choice = rng.randrange(5)
        if mb_choice == 0:
            m = 0xFF
        elif mb_choice == 1:
            m = 0x00
        elif mb_choice == 2:
            m = 0xF0
        elif mb_choice == 3:
            m = 0x0F
        else:
            m = rng.randrange(256)
        mask_bytes.append(_hex_byte(m))
    hm = _maybe_separate(''.join(mask_bytes), rng)
    hm = _truncate_to_128(hm)
    return hk, hm

def _make_hexmask_string(rng: random.Random):
    length = _safe_randint(rng, 8, 40)
    parts = []
    for _ in range(length):
        mode = rng.randrange(5)
        if mode == 0:
            parts.append(_hex_byte(rng.randrange(256)))
        elif mode == 1:
            parts.append("??")
        elif mode == 2:
            parts.append(f"{rng.choice(HEX_DIGITS)}?")
        elif mode == 3:
            parts.append(f"?{rng.choice(HEX_DIGITS)}")
        else:
            parts.append(rng.choice(["55","90","e9","cc","00","ff"]))
    sep = rng.choice([' ', ':', '-'])
    s = sep.join(parts)
    return s[:128] if len(s) > 128 else s

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    hk, hm = _make_hex_and_mask(rng)
    if rng.random() < 0.5:
        hm = _make_hexmask_string(rng)
    payload = hk.encode('ascii') + b"\x00" + hm.encode('ascii') + b"\x00"
    return payload[:4096]

import random
import textwrap
from typing import List

# Generate valid and interesting C source files that exercise C parsers in r_anal_cparse_file and r_egg_cfile_parser.
# The fuzzer stubs expect FUZZ_PARAM_FILENAME to point to a file containing C source code.
# We therefore return bytes that represent a C file. Keep it <= 4096 bytes.

KEYWORDS = [
    "auto","break","case","char","const","continue","default","do","double","else","enum","extern",
    "float","for","goto","if","inline","int","long","register","restrict","return","short","signed",
    "sizeof","static","struct","switch","typedef","union","unsigned","void","volatile","while","_Bool",
    "_Complex","_Imaginary"
]

TYPES = [
    "void","char","short","int","long","long long","unsigned","unsigned char","unsigned int",
    "float","double","long double","_Bool"
]

def _rand_ident(r: random.Random, minlen=1, maxlen=10) -> str:
    first = r.choice('_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
    rest = ''.join(r.choice('_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(r.randint(minlen-1, maxlen-1)))
    return first + rest

def _gen_const_expr(r: random.Random) -> str:
    # Mix integer literals, char constants, sizeof, and parentheses
    choices = []
    choices.append(str(r.randint(-1000, 1000)))
    choices.append(hex(r.randint(0, 0xFFFF)))
    choices.append(oct(r.randint(0, 0o7777)))
    choices.append("'a'")
    choices.append("'\\n'")
    choices.append(f"sizeof({_rand_ident(r)})")
    expr = r.choice(choices)
    # sometimes add simple arithmetic
    if r.random() < 0.5:
        expr = f"({expr} {r.choice(['+','-','*','/','%','&','|','^'])} {r.randint(0, 255)})"
    return expr

def _gen_macro(r: random.Random) -> str:
    name = _rand_ident(r).upper()
    if r.random() < 0.6:
        val = _gen_const_expr(r)
        return f"#define {name} {val}\n"
    else:
        # function-like macro
        params = ','.join(_rand_ident(r) for _ in range(r.randint(1,3)))
        body = f"({ _rand_ident(r) } + { _rand_ident(r) })"
        return f"#define {name}({params}) {body}\n"

def _gen_typedef(r: random.Random) -> str:
    base = r.choice(TYPES)
    alias = _rand_ident(r)
    ptrs = '*' * r.randint(0, 2)
    arr = '' if r.random() < 0.5 else f"[{r.randint(1,8)}]"
    return f"typedef {base} {ptrs}{alias}{arr};\n"

def _gen_struct_union(r: random.Random) -> str:
    kind = r.choice(['struct', 'union'])
    name = _rand_ident(r)
    fields = []
    for _ in range(r.randint(1,5)):
        t = r.choice(TYPES)
        ptr = '*' * r.randint(0,1)
        fname = _rand_ident(r)
        arr = '' if r.random() < 0.5 else f"[{r.randint(1,6)}]"
        fields.append(f"    {t} {ptr}{fname}{arr};")
    return f"{kind} {name} {{\n" + "\n".join(fields) + "\n};\n"

def _gen_enum(r: random.Random) -> str:
    name = _rand_ident(r)
    items = []
    val = None
    for i in range(r.randint(2,6)):
        ident = _rand_ident(r).upper()
        if r.random() < 0.5:
            val = r.randint(0, 20) if val is None else val + r.randint(1,3)
            items.append(f"    {ident} = {val}")
        else:
            items.append(f"    {ident}")
    return f"enum {name} {{\n" + ",\n".join(items) + "\n};\n"

def _gen_decl(r: random.Random) -> str:
    t = r.choice(TYPES)
    ptr = '*' * r.randint(0,2)
    name = _rand_ident(r)
    if r.random() < 0.4:
        # function prototype
        params: List[str] = []
        for _ in range(r.randint(0,3)):
            pt = r.choice(TYPES)
            pptr = '*' * r.randint(0,1)
            pname = _rand_ident(r)
            params.append(f"{pt} {pptr}{pname}")
        return f"{t} {ptr}{name}({', '.join(params) if params else 'void'});\n"
    else:
        # variable declaration
        arr = '' if r.random() < 0.6 else f"[{r.randint(1,10)}]"
        init = ''
        if arr and r.random() < 0.6 and ptr == '':
            init_vals = ', '.join(str(r.randint(0,9)) for _ in range(r.randint(1,5)))
            init = f" = {{{init_vals}}}"
        elif r.random() < 0.4 and ptr == '':
            init = f" = {_gen_const_expr(r)}"
        return f"{t} {ptr}{name}{arr}{init};\n"

def _gen_function(r: random.Random) -> str:
    ret = r.choice(TYPES)
    name = _rand_ident(r)
    params = []
    for _ in range(r.randint(0,3)):
        pt = r.choice(TYPES)
        pptr = '*' * r.randint(0,1)
        pname = _rand_ident(r)
        params.append(f"{pt} {pptr}{pname}")
    header = f"{ret} {name}({', '.join(params) if params else 'void'})" 
    # body with control flow, switch, loops, and some expressions
    body_lines = []
    # local vars
    for _ in range(r.randint(0,3)):
        body_lines.append(_gen_decl(r).rstrip(';') + ';')
    # if/else
    if r.random() < 0.8:
        body_lines.append(f"if ({_gen_const_expr(r)}) {{\n        (void)0;\n    }} else {{\n        (void)0;\n    }}")
    # for loop
    if r.random() < 0.8:
        i = _rand_ident(r)
        body_lines.append(textwrap.dedent(f"""
        for (int {i}=0; {i}<3; {i}++) {{
            (void){i};
        }}
        """).strip())
    # switch
    if r.random() < 0.7:
        s = _rand_ident(r)
        body_lines.append(textwrap.dedent(f"""
        switch ({_gen_const_expr(r)}) {{
        case 0: {{ int {s}=0; (void){s}; break; }}
        case 1: {{ break; }}
        default: break;
        }}
        """).strip())
    # return
    if ret == 'void':
        body_lines.append('return;')
    else:
        body_lines.append(f"return ({_gen_const_expr(r)});")
    body = "\n    ".join(body_lines)
    return f"{header}\n{{\n    {body}\n}}\n"

def _gen_attributes_pragmas(r: random.Random) -> str:
    chunks = []
    if r.random() < 0.5:
        chunks.append("#pragma pack(push, 1)\n")
    if r.random() < 0.5:
        chunks.append("#ifdef __GNUC__\n__attribute__((unused)) static int __attr_probe = 0;\n#endif\n")
    if r.random() < 0.5:
        chunks.append("#ifndef NULL\n#define NULL ((void*)0)\n#endif\n")
    return ''.join(chunks)

def _gen_includes(r: random.Random) -> str:
    incs = ["#include <stddef.h>", "#include <stdint.h>"]
    if r.random() < 0.7:
        incs.append("#include <stdio.h>")
    if r.random() < 0.5:
        incs.append("#include <string.h>")
    return "\n".join(incs) + "\n"

def _gen_translation_unit(r: random.Random) -> str:
    parts: List[str] = []
    parts.append("/* Generated C file for fuzzing C parsers */\n")
    parts.append(_gen_includes(r))
    parts.append(_gen_attributes_pragmas(r))
    # a few macros/typedefs/enums/structs
    for _ in range(r.randint(1,3)):
        parts.append(_gen_macro(r))
    for _ in range(r.randint(0,2)):
        parts.append(_gen_typedef(r))
    if r.random() < 0.8:
        parts.append(_gen_enum(r))
    if r.random() < 0.8:
        parts.append(_gen_struct_union(r))
    # some declarations
    for _ in range(r.randint(1,4)):
        parts.append(_gen_decl(r))
    # multiple functions including a main sometimes
    fun_count = r.randint(1,4)
    for _ in range(fun_count):
        parts.append(_gen_function(r))
    if r.random() < 0.7:
        # Provide a small main to be even more standard-like; parsers usually accept it even if unused
        parts.append("int main(void) { return 0; }\n")
    return "\n".join(parts)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Randomly select one of several profiles to bias content
    profile = r.choice(['control', 'types', 'macros', 'mixed'])
    tu = []
    if profile == 'control':
        # emphasize control flow and functions
        tu.append(_gen_includes(r))
        for _ in range(2):
            tu.append(_gen_function(r))
    elif profile == 'types':
        tu.append(_gen_includes(r))
        tu.append(_gen_enum(r))
        tu.append(_gen_struct_union(r))
        tu.append(_gen_typedef(r))
        tu.append(_gen_decl(r))
        tu.append(_gen_function(r))
    elif profile == 'macros':
        tu.append(_gen_includes(r))
        for _ in range(5):
            tu.append(_gen_macro(r))
        tu.append(_gen_function(r))
    else:
        tu.append(_gen_translation_unit(r))

    code = "\n".join(tu)
    # Ensure size limit
    b = code.encode('utf-8', 'surrogatepass')[:4096]
    # Guarantee newline termination
    if not b.endswith(b"\n"):
        b += b"\n"
    return b

import random
import string
from typing import List

# Target format: UTF-8 text with no embedded NULs, intended for QR encoding
# The stub removes embedded NULs and requires non-empty text.
# We will generate diverse valid UTF-8 strings likely to exercise encoder modes:
# - Numeric-only
# - Alphanumeric QR set
# - Mixed case with punctuation
# - UTF-8 multi-byte (CJK, emoji)
# - Long vs short, with newlines/spaces
# - URL-like, file path, JSON-like
# All without embedded NULs. We cap total size to <= 4096 bytes.

ALNUM_QR = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:"

CJK_BLOCKS = [
    (0x4E00, 0x9FFF),  # CJK Unified Ideographs
    (0x3040, 0x309F),  # Hiragana
    (0x30A0, 0x30FF),  # Katakana
]

EMOJI_POINTS = [
    0x1F600, 0x1F603, 0x1F604, 0x1F60D, 0x1F923, 0x1F44D, 0x1F680, 0x1F4A9,
    0x1F9E9, 0x1F9F8, 0x1F389, 0x1F381, 0x1F3AF, 0x1F9ED, 0x1F3C3, 0x1F4BB,
]

URL_PREFIXES = [
    "http://", "https://", "ftp://", "mailto:", "tel:", "wifi:",
]

def _rand_cjk(r: random.Random, n: int) -> str:
    s = []
    for _ in range(n):
        blk = r.choice(CJK_BLOCKS)
        cp = r.randint(blk[0], blk[1])
        s.append(chr(cp))
    return ''.join(s)

def _rand_emoji(r: random.Random, n: int) -> str:
    return ''.join(chr(r.choice(EMOJI_POINTS)) for _ in range(n))

def _rand_qr_alnum(r: random.Random, n: int) -> str:
    return ''.join(r.choice(ALNUM_QR) for _ in range(n))

def _rand_numeric(r: random.Random, n: int) -> str:
    return ''.join(r.choice(string.digits) for _ in range(n))

def _rand_ascii(r: random.Random, n: int) -> str:
    # printable ASCII excluding NUL
    chars = string.ascii_letters + string.digits + string.punctuation + ' '
    return ''.join(r.choice(chars) for _ in range(n))

def _rand_component(r: random.Random, max_len: int) -> str:
    kind = r.randint(0, 6)
    if kind == 0:
        return _rand_numeric(r, r.randint(1, max_len))
    if kind == 1:
        return _rand_qr_alnum(r, r.randint(1, max_len))
    if kind == 2:
        return _rand_ascii(r, r.randint(1, max_len))
    if kind == 3:
        # mixed CJK
        return _rand_cjk(r, r.randint(1, max_len // 2 + 1))
    if kind == 4:
        return _rand_emoji(r, r.randint(1, max_len // 2 + 1))
    if kind == 5:
        # URL-like
        host = _rand_ascii(r, r.randint(3, 10)).replace(' ', '').replace('"', '')
        path = _rand_ascii(r, r.randint(0, 12)).replace(' ', '-')
        return r.choice(URL_PREFIXES) + host + ".example/" + path
    # JSON-like
    key = _rand_ascii(r, r.randint(3, 8)).replace('"', '')
    val = _rand_ascii(r, r.randint(3, 12)).replace('"', '')
    return f"{{\"{key}\":\"{val}\"}}"

def _compose_message(r: random.Random, target_len: int) -> str:
    # Build a message by concatenating components with separators that encode well
    parts: List[str] = []
    while sum(len(p) for p in parts) < target_len:
        remaining = target_len - sum(len(p) for p in parts)
        comp = _rand_component(r, max(4, min(remaining, 64)))
        parts.append(comp)
        # add a separator sometimes
        if r.random() < 0.5 and sum(len(p) for p in parts) < target_len:
            parts.append(r.choice([" ", "\n", ",", ":", ";", "|"]))
    s = ''.join(parts)
    if not s:
        s = "A"
    return s

def _bias_lengths(r: random.Random) -> int:
    # Favor small to medium, but sometimes larger up to ~1000 bytes
    buckets = [16, 32, 64, 120, 240, 480, 960]
    weights = [20, 20, 20, 15, 12, 8, 5]
    return r.choices(buckets, weights=weights, k=1)[0]

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Decide overall size budget (must be <= 4096)
    length = _bias_lengths(r)

    # Occasionally force specific classes useful for QR modes
    mode = r.randint(0, 7)
    if mode == 0:
        # Pure numeric
        s = _rand_numeric(r, max(1, length))
    elif mode == 1:
        # QR alphanumeric set only
        s = _rand_qr_alnum(r, max(1, length))
    elif mode == 2:
        # ASCII text with punctuation
        s = _rand_ascii(r, length)
    elif mode == 3:
        # CJK heavy
        s = _rand_cjk(r, max(1, length // 2 + 1))
    elif mode == 4:
        # Emoji heavy
        s = _rand_emoji(r, max(1, length // 2 + 1))
    elif mode == 5:
        # URL-like with query
        base = _rand_component(r, 40)
        query = 'query=' + _rand_ascii(r, 8).replace(' ', '')
        s = base + ('?' if '?' not in base else '&') + query
    elif mode == 6:
        # JSON-like payload
        items = []
        for _ in range(r.randint(1, 5)):
            key = _rand_ascii(r, r.randint(3, 8)).replace('"', '')
            val = _rand_ascii(r, r.randint(3, 14)).replace('"', '')
            items.append(f"\"{key}\":\"{val}\"")
        s = '{' + ','.join(items) + '}'
        if len(s) < length:
            s += _rand_ascii(r, length - len(s))
    else:
        s = _compose_message(r, length)

    # Ensure no embedded NULs and valid UTF-8 by construction
    s = s.replace('\x00', '')
    if not s:
        s = 'A'

    # Enforce size limit and return UTF-8 bytes
    data = s.encode('utf-8', errors='strict')
    if len(data) > 4096:
        data = data[:4096]
        # Avoid cutting a multibyte in half: backtrack to valid UTF-8 boundary
        end = len(data)
        while end > 0:
            try:
                data[:end].decode('utf-8')
                data = data[:end]
                break
            except UnicodeDecodeError:
                end -= 1
        if end == 0:
            data = b"A"
    return data
